&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;TikTok Shop Strategy&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Own the TikTok Shop strategy for each client account - setting clear objectives, growth plans and trading priorities aligned to the client’s wider commercial goals.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Build and present strategic plans covering shop set-up, product and catalogue strategy, pricing and promotions, content, live shopping, creator and affiliate activity, and paid amplification.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Align TikTok Shop activity with each client’s trading calendar, key retail moments and wider THG Ingenuity services to maximise commercial impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Translate platform updates, new formats and social commerce trends into clear, actionable recommendations for clients.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;Delivery &amp;amp; Service Quality&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Take accountability for the end-to-end delivery of TikTok Shop services across your clients, ensuring work is delivered on time, on brief and to a consistently high standard.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Direct and support the Social Commerce Executives and wider delivery teams day to day - prioritising workload, reviewing outputs and stepping in early where delivery starts to drift.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Establish and maintain best-practice frameworks, processes and playbooks for TikTok Shop set-up, optimisation and campaign delivery.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Set quality standards and QA processes across listings, content, creator activity and reporting, so every client receives the same high level of service.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Coordinate effectively with creative, content, studio, paid social, ecommerce and operations teams so TikTok Shop activity is joined up and commercially aligned.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
